MonarchSectionCard(title = {{zone.title}}, description = {{zone.description}}, tone = MonarchTone.Danger) {
    Row(horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space3), verticalAlignment = Alignment.CenterVertically) {
        Column(modifier = Modifier.weight(1f)) {
            MonarchText(text = {{item.title}}, style = MonarchTextStyle.BodyStrong)
            MonarchText(text = {{item.description}}, style = MonarchTextStyle.Caption)
        }
    MonarchButton(
            text = {{item.action}},
            onClick = {
                step = "review"
                typed = ""
                open = true
            },
            variant = MonarchButtonVariant.Danger,
        )
    }
}
if (open) {
    // While the work runs, a swipe, back or a tap outside does not close the sheet.
    MonarchBottomSheet(onDismissRequest = { open = false }, title = {{item.action}}, dismissible = !deleting) {
        Column(
            modifier = Modifier.verticalScroll(rememberScrollState()),
            verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space4),
        ) {
            val stepNumber = listOf("review", "export", "reason", "confirm").indexOf(step) + 1
            if (stepNumber in 1..4 && step != "verify") {
                MonarchText(text = "Step $stepNumber of 4", style = MonarchTextStyle.Caption)
                Row(horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space1)) {
                    repeat(4) { index ->
                        MonarchProgress(
                            modifier = Modifier.weight(1f),
                            progress = if (index < stepNumber) 1f else 0f,
                            size = MonarchProgressSize.Sm,
                        )
                    }
                }
            }
            when (step) {
                "review" -> {
                    MonarchText(text = {{review.title}}, style = MonarchTextStyle.Title)
                    MonarchText(text = {{review.description}})
                    MonarchConsequenceList(
                        items = listOf(
                            MonarchConsequence(MonarchConsequenceKind.{{consequences.0.kind|pascal}}, {{consequences.0.label}}),
                            MonarchConsequence(MonarchConsequenceKind.{{consequences.1.kind|pascal}}, {{consequences.1.label}}),
                            MonarchConsequence(MonarchConsequenceKind.{{consequences.2.kind|pascal}}, {{consequences.2.label}}),
                        ),
                        grouped = true,
                    )
                    if (owned.isNotEmpty()) {
                        MonarchInlineNotice(
                            message = "You are the only owner of these workspaces. Transfer each one, or delete it, first.",
                            tone = MonarchTone.Warning,
                        )
                        owned.forEach { (name, members) ->
                            Row(verticalAlignment = Alignment.CenterVertically) {
                                MonarchText(text = "$name, $members members", modifier = Modifier.weight(1f))
                                MonarchButton(
                                    text = "Transfer or delete",
                                    onClick = {
                                        // Open the workspace's settings; once it is transferred or deleted:
                                        owned = owned.filterNot { it.first == name }
                                    },
                                    modifier = Modifier.semantics { contentDescription = "Transfer or delete $name" },
                                    size = MonarchButtonSize.Sm,
                                )
                            }
                        }
                    }
                    MonarchButton(
                        text = "Continue",
                        onClick = { step = "export" },
                        modifier = Modifier.fillMaxWidth(),
                        variant = MonarchButtonVariant.Primary,
                        enabled = owned.isEmpty(),
                    )
                }
                "export" -> {
                    @OptIn(ExperimentalMonarchApi::class)
                    MonarchDataExportRequest(
                        status = export,
                        onRequest = { export = MonarchDataExportStatus.Requested },
                    )
                    MonarchButton(
                        text = "Continue",
                        onClick = { step = "reason" },
                        modifier = Modifier.fillMaxWidth(),
                        variant = MonarchButtonVariant.Primary,
                    )
                }
                "reason" -> {
                    MonarchText(text = "Why are you leaving?", style = MonarchTextStyle.Title)
                    MonarchText(text = "Optional. Your answer helps us improve.")
                    MonarchSelect(
                        options = listOf(
                            MonarchSelectOption({{reasons.0.value}}, {{reasons.0.label}}),
                            MonarchSelectOption({{reasons.1.value}}, {{reasons.1.label}}),
                            MonarchSelectOption({{reasons.2.value}}, {{reasons.2.label}}),
                            MonarchSelectOption({{reasons.3.value}}, {{reasons.3.label}}),
                        ),
                        selected = reason,
                        onSelect = { reason = it },
                        label = "Reason",
                        placeholder = "Choose a reason",
                    )
                    MonarchTextField(
                        value = details,
                        onValueChange = { details = it },
                        label = "Anything else you want to tell us?",
                        singleLine = false,
                    )
                    MonarchButton(
                        text = "Continue",
                        onClick = { step = "confirm" },
                        modifier = Modifier.fillMaxWidth(),
                        variant = MonarchButtonVariant.Primary,
                    )
                }
                "confirm" -> {
                    MonarchText(text = "Confirm deletion", style = MonarchTextStyle.Title)
                    failure?.let { MonarchInlineNotice(message = it, tone = MonarchTone.Danger) }
                    MonarchTypeToConfirmInput(
                        phrase = email,
                        value = typed,
                        onValueChange = { typed = it },
                        label = "Type $email to confirm",
                    )
                    MonarchButton(
                        text = "Delete account",
                        onClick = { step = "verify" },
                        modifier = Modifier.fillMaxWidth(),
                        variant = MonarchButtonVariant.Danger,
                        enabled = MonarchTypeToConfirmInputDefaults.matches(typed, email),
                    )
                }
                "verify" -> MonarchStepUpAuthDialog(
                    onVerify = { _ ->
                        // Send the credential to the server; throw if it is refused.
                    },
                    description = "Deleting your account needs you to confirm your identity.",
                    methods = listOf(MonarchStepUpMethod.{{stepUp.methods.0|pascal}}, MonarchStepUpMethod.{{stepUp.methods.1|pascal}}),
                    onCancel = { step = "confirm" },
                    onVerified = {
                        deleting = true
                        failure = null
                        scope.launch {
                            // Delete on the server with reason and details.trim(). On failure:
                            // failure = "Your account couldn’t be deleted. Try again."; step = "confirm"
                            deleting = false
                            step = "done"
                        }
                    },
                    onVerifyingChange = { deleting = it },
                )
                else -> {
                    MonarchText(text = "Account deleted", style = MonarchTextStyle.Title)
                    MonarchText(text = "Your account has been removed. Thank you for the time you spent with us.")
                    MonarchButton(
                        text = "Done",
                        onClick = { open = false /* then sign out */ },
                        modifier = Modifier.fillMaxWidth(),
                        variant = MonarchButtonVariant.Primary,
                    )
                }
            }
            if (step != "done" && step != "verify") {
                MonarchButton(
                    text = "Cancel",
                    onClick = { open = false },
                    modifier = Modifier.fillMaxWidth(),
                    variant = MonarchButtonVariant.Ghost,
                )
            }
        }
    }
}

